#include <algorithm>
#include "voice_gate.hpp"
#include "orcsdr_vocoder.h"
#include <fstream>
#include <iostream>
#include <iomanip>
#include <string>
#include <cstring>
#include <cstdlib>
using namespace orcsdr::nxdn::voice;
unsigned parity(unsigned x){x^=x>>4;x^=x>>2;x^=x>>1;return x&1;}
unsigned val(const uint8_t* b,unsigned n){unsigned x=0;while(n--)x=x*2+*b++;return x;}
bool sacch(const uint8_t* wire,Frame& f){std::array<uint8_t,60> ord{};for(unsigned i=0;i<60;i++)ord[i%5*12+i/5]=wire[i];std::array<int8_t,72> code{};for(unsigned i=0,j=0;i<72;i++)code[i]=i%6==5?-1:int8_t(ord[j++]);std::array<unsigned,16>a{},b{};a.fill(10000);a[0]=0;std::array<std::array<uint8_t,16>,36> tr{};for(unsigned t=0;t<36;t++){b.fill(10000);for(unsigned s=0;s<16;s++)for(unsigned k=0;k<2;k++){unsigned reg=s*2+k,ns=reg&15,c=a[s];c+=code[t*2]>=0&&unsigned(code[t*2])!=parity(reg&0x19);c+=code[t*2+1]>=0&&unsigned(code[t*2+1])!=parity(reg&0x17);if(c<b[ns]){b[ns]=c;tr[t][ns]=uint8_t(s);}}a=b;}if(a[0]>4)return false;std::array<uint8_t,36>d{};unsigned s=0;for(unsigned t=36;t-->0;){d[t]=s&1;s=tr[t][s];}unsigned c=63;for(unsigned i=0;i<26;i++){auto v=(c>>5)^d[i];c=((c<<1)&63)^(v?0x27:0);}if(c!=val(d.data()+26,6)||s||val(d.data()+32,4))return false;f.structure=uint8_t(val(d.data(),2));f.ran=uint8_t(val(d.data()+2,6));std::copy_n(d.data()+8,18,f.fragment.begin());return true;}
int main(int argc,char** argv){if(argc!=4)return 2;bool rate96=std::string(argv[1])=="96";std::ifstream in(argv[2]);std::ofstream out(argv[3],std::ios::binary);if(!in||!out)return 3;Gate gate;orc_vocoder codec;orc_vocoder_reset(&codec);std::srand(1);std::string hex;uint64_t pos,prior=0,start=0;unsigned n=0,nonzero=0,correction=0,rejected=0;uint32_t ce=0,epoch=1;while(in>>pos>>hex){if(hex.size()!=96)return 4;std::array<uint8_t,384>b{};for(unsigned i=0;i<48;i++){auto byte=std::stoul(hex.substr(i*2,2),nullptr,16);for(unsigned j=0;j<8;j++)b[i*8+j]=(byte>>(7-j))&1;}if(val(b.data(),20)!=0xcdf59)return 5;unsigned lfsr=0xe4;for(unsigned i=20;i<384;i+=2){b[i]^=lfsr&1;lfsr=(lfsr>>1)|(((lfsr^(lfsr>>4))&1)<<8);}unsigned lich=0,fe=0;for(unsigned i=20;i<36;i+=2){lich=lich*2+b[i];fe+=!b[i+1];}Frame f;f.rate96=rate96;if(prior){auto stride=rate96?1920:3840;auto delta=pos-prior;auto step=(delta+stride/2)/stride;auto err=delta>step*stride?delta-step*stride:step*stride-delta;if(step!=1||err>3){++epoch;start=0;}else start+=192;}prior=pos;f.start=start;f.epoch=epoch;f.lich_valid=fe<=1&&parity(lich>>4)==(lich&1);f.rfct=lich>>6;f.function=(lich>>4)&3;f.steal=(lich>>2)&3;f.direction=(lich>>1)&1;f.sacch_valid=sacch(b.data()+36,f);std::copy_n(b.data()+96,288,f.body.begin());auto r=gate.consume(f);if(r.call_epoch!=ce){orc_vocoder_reset(&codec);ce=r.call_epoch;}std::cerr<<pos<<" LICH="<<std::hex<<lich<<std::dec<<" SACCH="<<f.sacch_valid<<" RAN="<<unsigned(f.ran)<<" structure="<<unsigned(f.structure)<<" privacy="<<unsigned(r.call.privacy)<<" source="<<r.call.source<<" dst="<<r.call.destination<<" frames="<<unsigned(r.count)<<"\n";for(unsigned j=0;j<r.count;j++){int16_t pcm[160];orc_vocoder_result vr{};if(!orc_vocoder_dmr(&codec,r.frames[j].data(),ORC_PRIVACY_CLEAR,pcm,&vr))return 6;correction+=vr.total;bool sound=false;for(auto x:pcm){sound|=x!=0;uint16_t s=uint16_t(x);out.put(char(s&255));out.put(char(s>>8));}nonzero+=sound;rejected+=vr.corrected>3;std::cerr<<"  AMBE errors="<<vr.total<<" flags="<<vr.flags<<" nonzero="<<sound<<"\n";n++;}}const auto& s=gate.stats();std::cerr<<"frames="<<n<<" nonzero="<<nonzero<<" corrections="<<correction<<" rejected="<<rejected<<" FACCH_ok="<<s.facch_ok<<" FACCH_bad="<<s.facch_bad<<" late_calls="<<s.late_calls<<"\n";return 0;}
